<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Bank details | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/vendor.css"></head><body class="dashboard-page"><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><nav class="header-actions"><a href="/vendor/payouts">Payouts</a><a href="/logout">Sign out</a></nav></header><main class="vendor-form-shell"><p class="eyebrow">Vendor workspace</p><h1>Bank details</h1><p class="form-intro">Keep your payout details and registered business state current.</p><?php if ($error): ?><p class="auth-error"><?= htmlspecialchars($error) ?></p><?php endif; ?><form class="vendor-form" method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><label>Registered business state<input name="state" maxlength="100" required value="<?= htmlspecialchars($vendorState) ?>"></label><label>Account holder<input name="account_holder" required value="<?= htmlspecialchars($details['account_holder']) ?>"></label><label>Bank name<input name="bank_name" required value="<?= htmlspecialchars($details['bank_name']) ?>"></label><label>Account number (last four digits)<input name="account_number_masked" pattern="[0-9]{4}" maxlength="4" required value="<?= htmlspecialchars($details['account_number_masked']) ?>"></label><label>IFSC code<input name="ifsc_code" required maxlength="20" value="<?= htmlspecialchars($details['ifsc_code']) ?>"></label><button class="button" type="submit">Save details <span>→</span></button></form></main></body></html>